int policy_mode;
unsigned long nodemask[2];
unsigned long max_nodes = 128;
unsigned long check_addr = (unsigned long)some_ptr;
long status;

// Retrieve thread's default policy (addr=0, flags=0)
status = get_mempolicy(
    &policy_mode,
    nodemask,
    max_nodes,
    0,   // addr=0 for thread policy
    0    // flags=0
);

// Check policy associated with a specific address
// flags might include MPOL_F_ADDR | MPOL_F_NODE
status = get_mempolicy(
    &policy_mode,
    nodemask,
    max_nodes,
    check_addr,
    MPOL_F_ADDR
);
